function bestTwoBookings(offers: number[][]): number {
  const a = [...offers].sort((x, y) => x[0] - y[0]);
  const n = a.length;
  const best = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) best[i] = Math.max(best[i + 1], a[i][2]);
  let ans = 0;
  for (const [, end, pay] of a) {
    let lo = 0, hi = n; // first index with start > end
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (a[mid][0] > end) hi = mid;
      else lo = mid + 1;
    }
    ans = Math.max(ans, pay + best[lo]);
  }
  return ans;
}

